// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { NavMain } from "@/blocks/sidebar-07/components/sidebar-07-nav-main";
import { appNav, appProjects, appTeams, appUser } from "@/blocks/sidebar-shared/sidebar-data";
import { NavProjects } from "@/blocks/sidebar-shared/sidebar-nav-app";
import { TeamSwitcher } from "@/blocks/sidebar-shared/sidebar-team-switcher";
import { NavUser } from "@/blocks/sidebar-shared/sidebar-user-menu";
import { Sidebar, SidebarContent, SidebarFooter, SidebarHeader, SidebarRail } from "@/components/ui/sidebar";
const nav = appNav.map(item => ({
  ...item,
  items: item.items?.map(sub => ({
    ...sub,
    isActive: sub.title === "Recent"
  }))
}));
export const AppSidebar = defineUi<UI.ComponentProps<typeof Sidebar>>("AppSidebar", [], (_props, {
  slots: _slots
}) => {
  const props = computed(() => omitProps(_props, []));
  return () => {
    return <Sidebar collapsible="icon" role="navigation" aria-label="Studio" {...domProps(props.value)}>
      <SidebarHeader>
        <TeamSwitcher teams={appTeams} />
      </SidebarHeader>
      <SidebarContent>
        <NavMain items={nav} />
        <NavProjects projects={appProjects} />
      </SidebarContent>
      <SidebarFooter>
        <NavUser user={appUser} />
      </SidebarFooter>
      <SidebarRail />
    </Sidebar>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import type { AppNavItem } from "@/blocks/sidebar-shared/sidebar-data";
import { Collapsible, CollapsibleContent, CollapsibleIndicator, CollapsibleTrigger } from "@/components/ui/collapsible";
import { Icon } from "@/components/ui/icon";
import { SidebarGroup, SidebarGroupLabel, SidebarMenu, SidebarMenuButton, SidebarMenuItem, SidebarMenuSub, SidebarMenuSubButton, SidebarMenuSubItem } from "@/components/ui/sidebar";
export const NavMain = defineUi<{
  items: AppNavItem[];
  label?: string;
}>("NavMain", ["items", "label"], (_props, {
  slots: _slots
}) => {
  const items = computed(() => _props["items"]);
  const label = computed(() => _props["label"] === undefined ? "Studio" as const : _props["label"]);
  return () => {
    return <SidebarGroup>
      <SidebarGroupLabel>{label.value}</SidebarGroupLabel>
      <SidebarMenu>
        {items.value.map(item => <Collapsible key={item.title} asChild defaultOpen={item.isActive}>
            <SidebarMenuItem>
              <CollapsibleTrigger asChild>
                <SidebarMenuButton tooltip={item.title}>
                  <Icon name={item.icon} />
                  <span class="truncate">{item.title}</span>
                  <CollapsibleIndicator class="ms-auto group-data-[collapsible=icon]:hidden" />
                </SidebarMenuButton>
              </CollapsibleTrigger>
              <CollapsibleContent>
                <SidebarMenuSub>
                  {item.items?.map(sub => <SidebarMenuSubItem key={sub.title}>
                      <SidebarMenuSubButton asChild isActive={sub.isActive}>
                        <a href={sub.url}>
                          <span>{sub.title}</span>
                        </a>
                      </SidebarMenuSubButton>
                    </SidebarMenuSubItem>)}
                </SidebarMenuSub>
              </CollapsibleContent>
            </SidebarMenuItem>
          </Collapsible>)}
      </SidebarMenu>
    </SidebarGroup>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { AppSidebar } from "@/blocks/sidebar-07/components/sidebar-07-app-sidebar";
import { containedClasses } from "@/blocks/sidebar-shared/sidebar-contained";
import { PageBody, PageHeader, PageNote, PageSheet } from "@/blocks/sidebar-shared/sidebar-page";
import { SidebarProvider } from "@/components/ui/sidebar";
const Page = defineUi<{
  contained?: boolean;
}>("Page", ["contained"], (_props, {
  slots: _slots
}) => {
  const contained = computed(() => _props["contained"] === undefined ? false : _props["contained"]);
  const c = computed(() => containedClasses(contained.value));
  return () => {
    return <SidebarProvider class={c.value.provider}>
      <AppSidebar class={c.value.sidebar} />
      <PageSheet class={c.value.inset}>
        <PageHeader crumbs={[{
          label: "Sketchbook" as const,
          href: "#sketchbook" as const
        }, "Recent"]} class="transition-[width,height] ease-linear group-has-data-[collapsible=icon]/sidebar-wrapper:h-12" />
        <PageBody title="Recent sketches" kicker="Sketchbook">
          <PageNote title="Nothing sketched today" pose="sketch">
            The button above squeezes the pad down to icons so the page gets all the room. On a phone it opens the pad instead.
          </PageNote>
        </PageBody>
      </PageSheet>
    </SidebarProvider>;
  };
});
export default Page;
